import React, { useState, useRef, useEffect } from 'react';
import { useStore } from '../../store/useStore';
import { generateVivaQuestions, gradeVivaAnswer, gradeVivaSession, groqChat } from '../../utils/aiService';
import { apiPost, apiGet } from '../../utils/api';

var API = 'http://localhost:5000/api';
function getToken() { return localStorage.getItem('examai_token'); }
var SESSION_KEY = 'dexam_viva_session';
var SR = window.SpeechRecognition || window.webkitSpeechRecognition;

// ── face-api CDN loader ──────────────────────────────────────
var FACE_LOADED = false, FACE_LOADING = false, FACE_CBS = [];
var MODEL_URL   = 'https://cdn.jsdelivr.net/npm/@vladmandic/face-api/model/';
function loadFaceAPI() {
  return new Promise(function(resolve, reject) {
    if (FACE_LOADED) { resolve(); return; }
    FACE_CBS.push({ resolve, reject });
    if (FACE_LOADING) return;
    FACE_LOADING = true;
    var s = document.createElement('script');
    s.src = 'https://cdn.jsdelivr.net/npm/@vladmandic/face-api/dist/face-api.js';
    s.onload = function() {
      // Load SSD MobileNet (more accurate) + TinyFaceDetector (fast fallback)
      Promise.all([
        window.faceapi.nets.ssdMobilenetv1.loadFromUri(MODEL_URL),
        window.faceapi.nets.tinyFaceDetector.loadFromUri(MODEL_URL),
      ]).then(function() {
        FACE_LOADED = true; FACE_CBS.forEach(function(c){c.resolve();}); FACE_CBS = [];
      }).catch(function(e) { FACE_CBS.forEach(function(c){c.reject(e);}); FACE_CBS = []; });
    };
    s.onerror = function(e) { FACE_CBS.forEach(function(c){c.reject(e);}); FACE_CBS = []; };
    document.head.appendChild(s);
  });
}

function restoreSession() {
  try { return JSON.parse(sessionStorage.getItem(SESSION_KEY) || 'null'); } catch(e) { return null; }
}

async function gradeAnswer(question, modelAnswer, studentAnswer) {
  if (!studentAnswer || !studentAnswer.trim())
    return { correct: false, score_pct: 0, verdict: 'No Answer', feedback: 'Student did not answer.', missing: modelAnswer };
  try {
    var raw = await groqChat(
      'You are a strict viva examiner. Return ONLY valid JSON.',
      'Question: ' + question + '\nModel Answer: ' + modelAnswer + '\nStudent Answer: ' + studentAnswer +
      '\nReturn: {"correct":bool,"score_pct":0-100,"verdict":"Correct|Partially Correct|Incorrect","feedback":"2-3 sentences","missing":"key point missed or None"}',
      400, 0.2
    );
    return JSON.parse(raw.replace(/```json|```/g,'').trim());
  } catch(e) {
    return { correct: false, score_pct: 0, verdict: 'Error', feedback: 'Grading error: ' + e.message, missing: '' };
  }
}

export default function VivaRoom() {
  var store = useStore();
  var _restore = restoreSession();

  var [phase,      setPhase]      = useState(_restore ? 'room' : 'setup');
  var [title,      setTitle]      = useState(_restore ? _restore.title : '');
  var [topic,      setTopic]      = useState(_restore ? _restore.topic : '');
  var savedVivaRef = useRef(_restore || null);

  // Questions & transcript
  var [questions,   setQuestions]   = useState([]);
  var [currentQ,    setCurrentQ]    = useState(0);
  var [transcript,  setTranscript]  = useState([]);
  var [loading,     setLoading]     = useState(false);

  // Oral flow state
  var [flowState,   setFlowState]   = useState('idle');
  // idle | speaking | listening | grading | saving
  var [liveWords,   setLiveWords]   = useState('');   // interim words
  var [fullAnswer,  setFullAnswer]  = useState('');   // final confirmed answer
  var [verdict,     setVerdict]     = useState(null);
  var [autoMsg,     setAutoMsg]     = useState('');   // status message

  // Manual override
  var [manualAnswer, setManualAnswer] = useState('');

  // Monitoring
  var [faceStatus,  setFaceStatus]  = useState('loading');
  var [faceCount,   setFaceCount]   = useState(0);
  var [violations,  setViolations]  = useState([]);  // array of violation messages
  var [camReady,      setCamReady]      = useState(false);
  var [studentConnected, setStudentConnected] = useState(false);

  // Generator
  var [genTopic, setGenTopic] = useState('');
  var [genCount, setGenCount] = useState(5);

  // Custom Q
  var [showCustomQ,    setShowCustomQ]    = useState(false);
  var [customQuestion, setCustomQuestion] = useState('');
  var [customModelAns, setCustomModelAns] = useState('');
  var [genModel,       setGenModel]       = useState(false);

  // Examiner notes
  var [examinerNotes, setExaminerNotes] = useState('');

  // Invite
  var [showInvite,  setShowInvite]  = useState(false);
  var [inviteMode,  setInviteMode]  = useState('account');
  var [inviteEmail, setInviteEmail] = useState('');
  var [students,    setStudents]    = useState([]);
  var [selectedStu, setSelectedStu] = useState([]);
  var [inviteMsg,   setInviteMsg]   = useState('');
  var [inviting,    setInviting]    = useState(false);

  // Alerts
  var [alerts,     setAlerts]     = useState([]);
  var [unread,     setUnread]     = useState(0);
  var [showAlerts, setShowAlerts] = useState(false);
  var alertLastRef = useRef(Date.now());
  var pollRef      = useRef(null);

  // Away
  var [examinerAway,   setExaminerAway]   = useState(false);
  var [awayCountdown,  setAwayCountdown]  = useState(600);
  var [examinerLocked, setExaminerLocked] = useState(false);
  var awayTimerRef = useRef(null);
  var awayStartRef = useRef(null);
  var graceRef     = useRef(null);

  // Results
  var [results,         setResults]         = useState(null);
  var [editableAnswers, setEditableAnswers] = useState([]);
  var [finalizing,      setFinalizing]      = useState(false);

  // Refs
  var videoRef        = useRef(null);    // admin's own camera (monitoring)
  var studentVidRef   = useRef(null);    // remote student video
  var streamRef       = useRef(null);    // admin local stream
  var canvasRef       = useRef(null);
  var peerRef         = useRef(null);    // RTCPeerConnection
  var recRef          = useRef(null);
  var synthRef        = useRef(window.speechSynthesis);
  var fullAnswerRef   = useRef('');
  var faceIntervalRef = useRef(null);
  var noFaceFrames    = useRef(0);
  var multiFaceFrames = useRef(0);
  var violCountRef    = useRef(0);
  var flowStateRef    = useRef('idle');
  var currentQRef     = useRef(0);
  var questionsRef    = useRef([]);
  var sigPollRef      = useRef(null);    // signaling poll interval

  // Keep refs fresh
  useEffect(function() { flowStateRef.current = flowState; }, [flowState]);
  useEffect(function() { currentQRef.current  = currentQ;  }, [currentQ]);
  useEffect(function() { questionsRef.current = questions; }, [questions]);

  // ── Mount ─────────────────────────────────────────────────
  useEffect(function() {
    if (_restore && _restore.viva_id) { setTimeout(startCamera, 400); startPolling(); }
    return function() { stopAll(); };
  }, []); // eslint-disable-line

  // ── Away detection ─────────────────────────────────────────
  useEffect(function() {
    if (phase !== 'room') return;
    function onVis() {
      if (document.hidden && !examinerAway && !examinerLocked) {
        graceRef.current = setTimeout(function() {
          if (document.hidden) { setExaminerAway(true); awayStartRef.current = Date.now(); setAwayCountdown(600); }
        }, 4000);
      } else if (!document.hidden) { clearTimeout(graceRef.current); }
    }
    document.addEventListener('visibilitychange', onVis);
    return function() { document.removeEventListener('visibilitychange', onVis); clearTimeout(graceRef.current); };
  }, [phase, examinerAway, examinerLocked]); // eslint-disable-line

  useEffect(function() {
    if (!examinerAway) { clearInterval(awayTimerRef.current); return; }
    awayTimerRef.current = setInterval(function() {
      var rem = 600 - Math.floor((Date.now() - awayStartRef.current) / 1000);
      if (rem <= 0) {
        clearInterval(awayTimerRef.current); setExaminerAway(false); setExaminerLocked(true);
        sessionStorage.removeItem(SESSION_KEY);
        var vid = savedVivaRef.current ? savedVivaRef.current.viva_id : null;
        if (vid) fetch(API+'/viva/'+vid+'/lock',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+getToken()},body:JSON.stringify({locked:true})}).catch(function(){});
      } else setAwayCountdown(rem);
    }, 1000);
    return function() { clearInterval(awayTimerRef.current); };
  }, [examinerAway]); // eslint-disable-line

  function examinerReturn() {
    clearInterval(awayTimerRef.current); clearTimeout(graceRef.current);
    setExaminerAway(false); setAwayCountdown(600); awayStartRef.current = null;
  }

  // ── Polling ─────────────────────────────────────────────────
  function startPolling() {
    alertLastRef.current = Date.now(); clearInterval(pollRef.current);
    pollRef.current = setInterval(async function() {
      try {
        var notifs = await apiGet('/notifications');
        var fresh = (notifs||[]).filter(function(n) {
          return new Date(n.created_at||0).getTime() > alertLastRef.current &&
            n.title && (n.title.includes('Left Viva')||n.title.includes('Returned')||n.title.includes('Removed'));
        });
        if (fresh.length) { alertLastRef.current = Date.now(); setAlerts(function(p){return fresh.concat(p).slice(0,40);}); setUnread(function(p){return p+fresh.length;}); }
      } catch(e){}
    }, 6000);
  }

  // ── Camera + face detection ────────────────────────────────
  async function startCamera() {
    try {
      var stream = await navigator.mediaDevices.getUserMedia({ video:{ width:{ ideal:640 }, height:{ ideal:480 }, facingMode:'user' }, audio:false });
      streamRef.current = stream;
      var iv = setInterval(function() {
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          clearInterval(iv);
          videoRef.current.onloadedmetadata = function() {
            setCamReady(true);
            startFaceDetection();
            setTimeout(setupWebRTC, 1000); // start WebRTC after camera ready
          };
        }
      }, 200);
    } catch(e) { setFaceStatus('unavailable'); }
  }

  // ── WebRTC: Admin creates offer, student answers ────────────
  async function setupWebRTC() {
    var vivaId = savedVivaRef.current ? savedVivaRef.current.viva_id : null;
    if (!vivaId || !streamRef.current) return;
    try {
      var pc = new RTCPeerConnection({
        iceServers: [{ urls: 'stun:stun.l.google.com:19302' }, { urls: 'stun:stun1.l.google.com:19302' }]
      });
      peerRef.current = pc;
      // Add admin's local tracks
      streamRef.current.getTracks().forEach(function(t) { pc.addTrack(t, streamRef.current); });
      // When remote (student) track arrives — show in studentVidRef
      pc.ontrack = function(e) {
        if (studentVidRef.current && e.streams && e.streams[0]) {
          studentVidRef.current.srcObject = e.streams[0];
          setStudentConnected(true);
        }
      };
      // ICE candidates
      pc.onicecandidate = function(e) {
        if (e.candidate) {
          fetch(API + '/viva/' + vivaId + '/signal/candidate', {
            method:'POST', headers:{'Content-Type':'application/json',Authorization:'Bearer '+getToken()},
            body: JSON.stringify({ role:'admin', candidate: e.candidate })
          }).catch(function(){});
        }
      };
      // Create offer
      var offer = await pc.createOffer();
      await pc.setLocalDescription(offer);
      await fetch(API + '/viva/' + vivaId + '/signal/offer', {
        method:'POST', headers:{'Content-Type':'application/json',Authorization:'Bearer '+getToken()},
        body: JSON.stringify({ offer: pc.localDescription })
      });
      // Poll for student answer
      sigPollRef.current = setInterval(async function() {
        try {
          var r = await fetch(API + '/viva/' + vivaId + '/signal/answer', { headers:{Authorization:'Bearer '+getToken()} });
          var data = await r.json();
          if (data.answer && pc.remoteDescription === null) {
            await pc.setRemoteDescription(new RTCSessionDescription(data.answer));
            clearInterval(sigPollRef.current);
            // Add student ICE candidates
            var cr = await fetch(API + '/viva/' + vivaId + '/signal/candidates/student', { headers:{Authorization:'Bearer '+getToken()} });
            var cd = await cr.json();
            (cd.candidates||[]).forEach(function(c) { pc.addIceCandidate(new RTCIceCandidate(c)).catch(function(){}); });
          }
        } catch(e) {}
      }, 2000);
    } catch(e) { console.warn('WebRTC setup failed:', e); }
  }

  async function startFaceDetection() {
    try {
      await loadFaceAPI();
      var opts = new window.faceapi.SsdMobilenetv1Options({ minConfidence: 0.5, maxResults: 10 }); // SSD is much more accurate
      faceIntervalRef.current = setInterval(async function() {
        if (!videoRef.current || videoRef.current.readyState < 2) return;
        try {
          var dets = await window.faceapi.detectAllFaces(videoRef.current, opts);
          var count = dets ? dets.length : 0;
          setFaceCount(count);

          // Draw boxes on canvas
          if (canvasRef.current && dets && dets.length) {
            var cv  = canvasRef.current;
            var vid = videoRef.current;
            var dispW = vid.clientWidth  || 200;
            var dispH = vid.clientHeight || 160;
            cv.width  = dispW; cv.height = dispH;
            var natW  = vid.videoWidth  || dispW;
            var natH  = vid.videoHeight || dispH;
            var scale = Math.max(dispW / natW, dispH / natH);
            var offX  = (dispW - natW * scale) / 2;
            var offY  = (dispH - natH * scale) / 2;
            var ctx   = cv.getContext('2d');
            ctx.clearRect(0, 0, dispW, dispH);
            dets.forEach(function(d) {
              var box = d.box || (d.detection && d.detection.box);
              if (!box) return;
              var x = box.x * scale + offX, y = box.y * scale + offY;
              var w = box.width * scale,    h = box.height * scale;
              var color = count > 1 ? '#ef4444' : '#22c55e';
              ctx.shadowColor = color; ctx.shadowBlur = 8;
              ctx.strokeStyle = color; ctx.lineWidth = 2.5;
              ctx.strokeRect(x, y, w, h);
              ctx.shadowBlur = 0;
              // Corner marks
              var cL = Math.min(w,h)*0.18;
              ctx.strokeStyle='#fff'; ctx.lineWidth=2;
              [[x,y,1,0,0,1],[x+w,y,-1,0,0,1],[x,y+h,1,0,0,-1],[x+w,y+h,-1,0,0,-1]].forEach(function(c){
                ctx.beginPath(); ctx.moveTo(c[0]+c[2]*cL,c[1]); ctx.lineTo(c[0],c[1]); ctx.lineTo(c[0],c[1]+c[5]*cL); ctx.stroke();
              });
              var label = count > 1 ? '⚠ EXTRA' : '✓ Face';
              ctx.font='bold 10px monospace';
              var tw=ctx.measureText(label).width+8;
              ctx.fillStyle=color+'cc'; ctx.fillRect(x, y>16?y-16:y+h, tw, 16);
              ctx.fillStyle='#fff'; ctx.fillText(label, x+4, y>16?y-4:y+h+12);
            });
          }

          // Status + violations
          if (count === 0) {
            setFaceStatus('no_face');
            noFaceFrames.current++;
            multiFaceFrames.current = 0;
            if (noFaceFrames.current >= 24) {  // ~12s — very conservative
              noFaceFrames.current = 0;
              addViolation('No face detected — examiner may have left camera');
            }
          } else if (count > 1) {
            setFaceStatus('multiple');
            multiFaceFrames.current++;
            noFaceFrames.current = 0;
            if (multiFaceFrames.current >= 12) {  // ~6s sustained before flagging
              multiFaceFrames.current = 0;
              addViolation('Multiple faces detected — ' + count + ' people in frame');
            }
          } else {
            setFaceStatus('ok');
            noFaceFrames.current   = 0;
            multiFaceFrames.current= 0;
          }
        } catch(e2) {}
      }, 500);
    } catch(e) { setFaceStatus('fallback'); }
  }

  function addViolation(msg) {
    violCountRef.current++;
    setViolations(function(prev) {
      return [{ time: new Date().toLocaleTimeString(), msg, n: violCountRef.current }].concat(prev).slice(0, 20);
    });
  }

  function stopAll() {
    clearInterval(pollRef.current); clearInterval(awayTimerRef.current);
    clearInterval(faceIntervalRef.current); clearInterval(sigPollRef.current);
    clearTimeout(graceRef.current);
    stopSTT(); synthRef.current && synthRef.current.cancel();
    if (peerRef.current) { try { peerRef.current.close(); } catch(e){} peerRef.current = null; }
    if (streamRef.current) streamRef.current.getTracks().forEach(function(t){t.stop();});
  }

  // ── TTS: read question ──────────────────────────────────────
  function speakQuestion(text, onDone) {
    if (!window.speechSynthesis || !text) { onDone && onDone(); return; }
    synthRef.current.cancel();
    var utt = new SpeechSynthesisUtterance(text);
    utt.rate  = 0.88; utt.pitch = 1;
    utt.onend = function() { setFlowState('listening'); flowStateRef.current = 'listening'; onDone && onDone(); startSTT(); };
    synthRef.current.speak(utt);
    setFlowState('speaking');
  }

  // ── STT: auto-capture with silence detection ────────────────
  var silenceTimer = useRef(null);

  function startSTT() {
    if (!SR) { setAutoMsg('No speech recognition — type answer below'); return; }
    stopSTT();
    fullAnswerRef.current = '';
    setFullAnswer(''); setLiveWords('');

    var rec = new SR();
    rec.continuous     = true;
    rec.interimResults = true;
    rec.lang           = 'en-US';

    rec.onresult = function(e) {
      var fin = '', inter = '';
      for (var i = e.resultIndex; i < e.results.length; i++) {
        if (e.results[i].isFinal) fin   += e.results[i][0].transcript + ' ';
        else                       inter += e.results[i][0].transcript;
      }
      if (fin) {
        fullAnswerRef.current += fin;
        setFullAnswer(fullAnswerRef.current);
      }
      setLiveWords(inter);

      // Reset silence timer on any speech
      clearTimeout(silenceTimer.current);
      silenceTimer.current = setTimeout(function() {
        // 3 seconds of silence = done speaking
        if (flowStateRef.current === 'listening') {
          autoGradeAndSave();
        }
      }, 3000);
    };

    rec.onerror = function(e) { if (e.error !== 'no-speech' && e.error !== 'aborted') setAutoMsg('Mic: ' + e.error); };
    rec.onend   = function() { if (recRef.current && flowStateRef.current === 'listening') { try { rec.start(); } catch(ex){} } };
    rec.start();
    recRef.current = rec;
  }

  function stopSTT() {
    clearTimeout(silenceTimer.current);
    if (recRef.current) { try { recRef.current.stop(); } catch(e){} recRef.current = null; }
    setLiveWords('');
  }

  // ── Auto grade → auto save → auto next ────────────────────
  async function autoGradeAndSave() {
    stopSTT();
    setFlowState('grading'); flowStateRef.current = 'grading';
    setAutoMsg('Grading answer…');

    var qs  = questionsRef.current;
    var idx = currentQRef.current;
    if (!qs[idx]) return;

    var ans = (manualAnswer.trim() || fullAnswerRef.current.trim() || '(no answer)');
    var q   = qs[idx];

    var v = await gradeAnswer(q.question, q.model_answer, ans);
    setVerdict(v);

    // Auto-save to transcript
    var entry = {
      question: q.question, model_answer: q.model_answer,
      student_answer: ans, notes: examinerNotes, verdict: v, _custom: q._custom||false,
    };

    setFlowState('saving'); flowStateRef.current = 'saving';
    setAutoMsg('Saved Q' + (idx+1) + ' — ' + v.verdict + ' (' + v.score_pct + '%)');

    setTranscript(function(t) { return t.concat([entry]); });
    setFullAnswer(''); fullAnswerRef.current = '';
    setManualAnswer(''); setExaminerNotes(''); setVerdict(null); setLiveWords('');

    // Auto-advance to next question
    var nextIdx = idx + 1;
    if (nextIdx < qs.length) {
      setTimeout(function() {
        setCurrentQ(nextIdx); currentQRef.current = nextIdx;
        setFlowState('speaking'); flowStateRef.current = 'speaking';
        setAutoMsg('');
        speakQuestion(qs[nextIdx].question);
      }, 1200);
    } else {
      setFlowState('idle'); flowStateRef.current = 'idle';
      setAutoMsg('All questions done — click End & Grade');
    }
  }

  // ── Manual grade & save (override button) ─────────────────
  async function handleManualGradeAndSave() {
    var ans = manualAnswer.trim() || fullAnswer.trim();
    if (!ans || !questions[currentQ]) return;
    stopSTT();
    setFlowState('grading');
    var v = await gradeAnswer(questions[currentQ].question, questions[currentQ].model_answer, ans);
    setVerdict(v);
    var entry = { question: questions[currentQ].question, model_answer: questions[currentQ].model_answer, student_answer: ans, notes: examinerNotes, verdict: v, _custom: questions[currentQ]._custom||false };
    setTranscript(function(t){ return t.concat([entry]); });
    setFullAnswer(''); fullAnswerRef.current=''; setManualAnswer(''); setExaminerNotes(''); setVerdict(null);
    var next = currentQ + 1;
    if (next < questions.length) {
      setCurrentQ(next); currentQRef.current=next;
      setTimeout(function(){ speakQuestion(questions[next].question); }, 800);
    } else { setFlowState('idle'); setAutoMsg('All questions done!'); }
  }

  // ── Start viva (speak first Q) ─────────────────────────────
  function startVivaFlow() {
    if (questions.length === 0) { store.addToast('Add questions first', 'error'); return; }
    setCurrentQ(0); currentQRef.current = 0;
    setFlowState('speaking');
    speakQuestion(questions[0].question);
  }

  // ── Generate questions ─────────────────────────────────────
  async function handleGenerateQ() {
    if (!genTopic.trim()) return;
    setLoading(true);
    try {
      var existing = questions.map(function(q){ return q.question||''; });
      var newQs = await generateVivaQuestions(genTopic, genCount, existing);
      setQuestions(function(prev){ var next=prev.concat(newQs); questionsRef.current=next; return next; });
    } catch(e) { alert('Generation failed: ' + e.message); }
    setLoading(false);
  }

  async function handleAddCustomQuestion() {
    if (!customQuestion.trim()) return;
    var ma = customModelAns.trim();
    if (!ma) {
      setGenModel(true);
      try { ma = await groqChat('You are a subject expert.','Model answer (3-5 sentences) for viva: '+customQuestion, 300, 0.5); } catch(e){ ma='(unavailable)'; }
      setGenModel(false);
    }
    var q = { question: customQuestion, model_answer: ma, _custom: true };
    setQuestions(function(prev){ var next=prev.concat([q]); questionsRef.current=next; return next; });
    setCustomQuestion(''); setCustomModelAns(''); setShowCustomQ(false);
  }

  async function handleStartRoom() {
    if (!title.trim()) return;
    setLoading(true);
    try {
      var r = await apiPost('/viva', { title, topic, questions:[] });
      var vivaData = { viva_id: r.viva_id, title, topic };
      savedVivaRef.current = vivaData;
      sessionStorage.setItem(SESSION_KEY, JSON.stringify(vivaData));
      setPhase('room'); setTimeout(startCamera, 300); startPolling();
    } catch(e) { alert(e.message); }
    setLoading(false);
  }

  async function handleEndGrade() {
    stopAll(); sessionStorage.removeItem(SESSION_KEY);
    setLoading(true); setPhase('grading');
    try {
      var graded = [];
      for (var i=0; i<transcript.length; i++) {
        var t = transcript[i];
        var v2 = t.verdict || await gradeAnswer(t.question, t.model_answer, t.student_answer);
        graded.push(Object.assign({}, t, { correct: v2.correct, score_pct: v2.score_pct, ai_feedback: v2.feedback, ai_verdict: v2.verdict, missing: v2.missing }));
      }
      var tText = graded.map(function(t,i){ return 'Q'+(i+1)+': '+t.question+'\nStudent: '+t.student_answer+'\nModel: '+t.model_answer; }).join('\n\n');
      var report = await gradeVivaSession(tText);
      var edited = graded.map(function(t,i){
        var ra=(report.answers&&report.answers[i])||{};
        return { question:t.question, model_answer:t.model_answer, student_answer:t.student_answer, notes:t.notes||'', _custom:t._custom||false,
          verdict:t.ai_verdict||ra.verdict||'Not graded', score_pct:t.score_pct||ra.score||0, feedback:t.ai_feedback||ra.feedback||'', correct:t.correct||ra.correct||false, missing:t.missing||'' };
      });
      setEditableAnswers(edited); setResults(report);
      var vivaId = savedVivaRef.current ? savedVivaRef.current.viva_id : null;
      if (vivaId) await apiPost('/viva/'+vivaId+'/end', { ended:true });
      setPhase('results');
    } catch(e) { alert('Grading failed: '+e.message); setPhase('room'); }
    setLoading(false);
  }

  function updateAnswer(idx,field,val) {
    setEditableAnswers(function(prev){ var arr=prev.slice(); arr[idx]=Object.assign({},arr[idx]); arr[idx][field]=val;
      if(field==='verdict'){arr[idx].correct=val==='Correct';arr[idx].score_pct=val==='Correct'?100:val==='Partially Correct'?50:0;} return arr; });
  }

  async function handleFinalize() {
    setFinalizing(true);
    var ts=editableAnswers.length>0?Math.round(editableAnswers.reduce(function(a,e){return a+(Number(e.score_pct)||0);},0)/editableAnswers.length):0;
    var grade=ts>=90?'A+':ts>=80?'A':ts>=70?'B':ts>=60?'C':ts>=50?'D':'F';
    var cc=editableAnswers.filter(function(e){return e.correct;}).length;
    var ft=editableAnswers.map(function(e,i){
      return '━━━ Q'+(i+1)+(e._custom?' [Examiner]':'')+'\nQ: '+e.question+'\nModel: '+e.model_answer+'\nStudent: '+e.student_answer+'\nVerdict: '+e.verdict+' ('+e.score_pct+'%)\nFeedback: '+e.feedback+(e.missing&&e.missing!=='None'?'\nMissing: '+e.missing:'')+(e.notes?'\nNotes: '+e.notes:'');
    }).join('\n\n');
    try {
      var vivaId=savedVivaRef.current?savedVivaRef.current.viva_id:null;
      if(vivaId) await apiPost('/viva/'+vivaId+'/result',{total_score:ts,grade,correct_count:cc,full_transcript:ft,ai_report:Object.assign({},results,{answers:editableAnswers,total_score:ts,grade})});
      setResults(function(r){return Object.assign({},r,{total_score:ts,grade,correct_count:cc});});
      savedVivaRef.current=null; setPhase('final');
    } catch(e){alert('Save failed: '+e.message);}
    setFinalizing(false);
  }

  function copyRoomId(){navigator.clipboard.writeText(savedVivaRef.current?savedVivaRef.current.viva_id:'').then(function(){alert('Copied!');});}
  async function loadStudents(){try{setStudents((await apiGet('/students'))||[]);}catch(e){}}
  function toggleStudent(id){setSelectedStu(function(p){return p.includes(id)?p.filter(function(x){return x!==id;}):p.concat([id]);});}
  async function sendInvites(){
    var vivaId=savedVivaRef.current?savedVivaRef.current.viva_id:null;
    if(!vivaId){alert('No room yet');return;}
    setInviting(true);setInviteMsg('');
    try{
      if(inviteMode==='account'&&selectedStu.length>0){var n=0;for(var i=0;i<selectedStu.length;i++){var s=students.find(function(x){return x.user_id===selectedStu[i];});if(s){await apiPost('/notifications',{title:'Viva Invitation — '+title,message:'Invited to "'+title+'". Room: '+vivaId,type:'info',recipient_id:s.user_id,viva_room_id:vivaId});n++;}}setInviteMsg('Sent to '+n+'.');setSelectedStu([]);}
      else if(inviteMode==='email'&&inviteEmail.trim()){await apiPost('/viva/invite',{emails:inviteEmail.split(',').map(function(e){return e.trim();}),title,topic,vivaId});setInviteMsg('Sent!');setInviteEmail('');}
    }catch(e){setInviteMsg('Error: '+e.message);}
    setInviting(false);
  }

  function resetAll(){
    sessionStorage.removeItem(SESSION_KEY);stopAll();
    setPhase('setup');setResults(null);setTranscript([]);setQuestions([]);setEditableAnswers([]);
    savedVivaRef.current=null;setTitle('');setTopic('');setExaminerLocked(false);setExaminerAway(false);
    setFullAnswer('');setManualAnswer('');setVerdict(null);setCurrentQ(0);setFlowState('idle');setCamReady(false);setViolations([]);
  }

  // Face status colours
  var fsColor = { ok:'#16a34a', no_face:'#d97706', multiple:'#dc2626', loading:'#9ca3af', fallback:'#9ca3af', unavailable:'#dc2626' };
  var fsLabel = { ok:'✅ Face OK', no_face:'⚠ No Face', multiple:'🚫 Multiple Faces!', loading:'Loading AI…', fallback:'Basic', unavailable:'Cam Off' };

  // Flow status
  var flowColor = { idle:'#9ca3af', speaking:'#a78bfa', listening:'#dc2626', grading:'#d97706', saving:'#16a34a' };
  var flowLabel = { idle:'Ready', speaking:'🔊 Speaking…', listening:'🎤 Listening…', grading:'⚡ Grading…', saving:'💾 Saved!' };

  // ════ SETUP ════════════════════════════════════════════════
  if (phase==='setup') return (
    <div className="viva-dark fade-up">
      <div style={{maxWidth:520,margin:'60px auto',textAlign:'center'}}>
        <div style={{fontSize:'3rem',marginBottom:16}}>🎙</div>
        <div style={{fontFamily:'Space Grotesk,sans-serif',fontWeight:800,fontSize:'1.6rem',color:'#fff',marginBottom:24}}>Start Oral Viva Room</div>
        <div className="card" style={{textAlign:'left'}}>
          <div className="form-group"><label className="form-label">Session Title *</label><input className="form-input" value={title} onChange={function(e){setTitle(e.target.value);}} placeholder="e.g. CS Final Viva"/></div>
          <div className="form-group"><label className="form-label">Topic</label><input className="form-input" value={topic} onChange={function(e){setTopic(e.target.value);}} placeholder="e.g. Data Structures"/></div>
          <div style={{padding:'10px 14px',background:'rgba(124,58,237,.1)',border:'1px solid rgba(124,58,237,.25)',borderRadius:8,marginBottom:14,fontSize:'0.82rem',color:'#a78bfa'}}>
            🎤 <strong>Oral Viva:</strong> Questions read aloud via TTS → student speaks → STT auto-transcribes → Groq auto-grades → moves to next question. Marks generated automatically.
          </div>
          <button className="btn btn-primary btn-lg" style={{width:'100%',justifyContent:'center'}} onClick={handleStartRoom} disabled={loading||!title.trim()}>{loading?'Creating…':'🚀 Start Viva Room'}</button>
        </div>
      </div>
    </div>
  );

  // ════ AWAY ══════════════════════════════════════════════════
  if (examinerAway&&phase==='room') {
    var am=Math.floor(awayCountdown/60),as2=awayCountdown%60;
    return (
      <div style={{minHeight:'calc(100vh - 60px)',display:'flex',alignItems:'center',justifyContent:'center',flexDirection:'column',background:'#0d0d14'}}>
        <div style={{fontSize:'3rem',marginBottom:14}}>⏸</div>
        <div style={{fontFamily:'Space Grotesk,sans-serif',fontWeight:800,fontSize:'1.5rem',color:'#fff',marginBottom:6}}>You Left the Viva Room</div>
        <div style={{fontFamily:'JetBrains Mono,monospace',fontSize:'3.5rem',fontWeight:900,color:awayCountdown<120?'#dc2626':'#f59e0b',letterSpacing:5}}>{String(am).padStart(2,'0')}:{String(as2).padStart(2,'0')}</div>
        <div style={{fontSize:'0.82rem',color:'#6b7280',marginTop:8,marginBottom:28}}>Return within 10 min</div>
        <button className="btn btn-primary btn-lg" onClick={examinerReturn}>▶ Return to Viva Room</button>
      </div>
    );
  }
  if (examinerLocked) return (
    <div style={{minHeight:'calc(100vh - 60px)',display:'flex',alignItems:'center',justifyContent:'center',flexDirection:'column',background:'#0d0d14',padding:24}}>
      <div style={{textAlign:'center',background:'rgba(220,38,38,.06)',border:'1px solid rgba(220,38,38,.2)',borderRadius:20,padding:'44px 52px',maxWidth:460}}>
        <div style={{fontSize:'3.5rem',marginBottom:14}}>🔒</div>
        <div style={{fontFamily:'Space Grotesk,sans-serif',fontWeight:800,fontSize:'1.4rem',color:'#fff',marginBottom:8}}>Session Expired</div>
        <div style={{color:'#9ca3af',marginBottom:28}}>Away 10+ minutes. Session terminated.</div>
        <button className="btn btn-outline" onClick={resetAll}>Start New Session</button>
      </div>
    </div>
  );

  // ════ GRADING ═══════════════════════════════════════════════
  if (phase==='grading') return (
    <div className="viva-dark" style={{display:'flex',alignItems:'center',justifyContent:'center',minHeight:'calc(100vh - 60px)',flexDirection:'column',gap:16}}>
      <div className="spinner" style={{width:52,height:52,borderWidth:4}}/>
      <div style={{color:'#a78bfa',fontWeight:700,fontSize:'1.15rem'}}>Groq AI grading {transcript.length} oral answers…</div>
    </div>
  );

  // ════ RESULTS ═══════════════════════════════════════════════
  if (phase==='results'&&results) {
    var totalNow=editableAnswers.length>0?Math.round(editableAnswers.reduce(function(a,e){return a+(Number(e.score_pct)||0);},0)/editableAnswers.length):0;
    var gradeNow=totalNow>=90?'A+':totalNow>=80?'A':totalNow>=70?'B':totalNow>=60?'C':totalNow>=50?'D':'F';
    var gc2=gradeNow==='A'||gradeNow==='A+'?'#16a34a':gradeNow==='F'?'#dc2626':gradeNow==='B'?'#2563eb':'#d97706';
    return (
      <div className="fade-up">
        <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',marginBottom:20,flexWrap:'wrap',gap:12}}>
          <div><div className="page-title">📊 Oral Viva Results</div><div style={{fontSize:'0.82rem',color:'var(--text3)',marginTop:3}}>Auto-graded by Groq. Edit if needed, then Finalize.</div></div>
          <button className="btn btn-success" onClick={handleFinalize} disabled={finalizing}>{finalizing?'Saving…':'✅ Finalize & Save'}</button>
        </div>
        <div className="card" style={{marginBottom:20,borderLeft:'4px solid '+gc2}}>
          <div style={{display:'flex',alignItems:'center',gap:24,flexWrap:'wrap'}}>
            <div style={{textAlign:'center'}}><div style={{fontFamily:'Space Grotesk,sans-serif',fontWeight:900,fontSize:'3.5rem',color:gc2,lineHeight:1}}>{totalNow}%</div><div style={{fontSize:'0.72rem',color:'var(--text3)'}}>SCORE</div></div>
            <div style={{textAlign:'center'}}><div style={{fontFamily:'Space Grotesk,sans-serif',fontWeight:900,fontSize:'2.5rem',color:gc2}}>{gradeNow}</div><div style={{fontSize:'0.72rem',color:'var(--text3)'}}>GRADE</div></div>
            <div style={{textAlign:'center'}}><div style={{fontWeight:700,fontSize:'1.5rem',color:'#16a34a'}}>{editableAnswers.filter(function(e){return e.correct;}).length}</div><div style={{fontSize:'0.72rem',color:'var(--text3)'}}>CORRECT</div></div>
            <div style={{textAlign:'center'}}><div style={{fontWeight:700,fontSize:'1.5rem',color:'#dc2626'}}>{editableAnswers.filter(function(e){return !e.correct;}).length}</div><div style={{fontSize:'0.72rem',color:'var(--text3)'}}>INCORRECT</div></div>
            <div style={{flex:1,minWidth:200}}>
              <div style={{height:10,background:'var(--surface3)',borderRadius:5,overflow:'hidden'}}><div style={{height:'100%',width:totalNow+'%',background:gc2,borderRadius:5}}/></div>
            </div>
          </div>
        </div>
        {results.overall_feedback&&<div className="card" style={{marginBottom:20,background:'var(--accent-glow)',borderColor:'var(--accent-light)'}}><div style={{fontSize:'0.72rem',fontWeight:700,color:'var(--accent)',letterSpacing:1,marginBottom:8,fontFamily:'JetBrains Mono,monospace'}}>AI OVERALL FEEDBACK</div><div style={{fontSize:'0.9rem',lineHeight:1.7,color:'var(--text2)'}}>{results.overall_feedback}</div></div>}
        {editableAnswers.map(function(entry,i){
          var col=entry.correct?'#16a34a':entry.verdict==='Partially Correct'?'#d97706':'#dc2626';
          return (
            <div key={i} className="card" style={{marginBottom:14,borderLeft:'4px solid '+col}}>
              <div style={{display:'flex',gap:8,marginBottom:10,flexWrap:'wrap',alignItems:'center'}}>
                <span className="badge badge-primary" style={{fontSize:'0.7rem'}}>Q{i+1}</span>
                {entry._custom&&<span className="badge badge-warning" style={{fontSize:'0.7rem'}}>✏ Examiner's Q</span>}
                <span style={{fontWeight:700,fontSize:'0.95rem'}}>{entry.question}</span>
                <span style={{marginLeft:'auto',fontWeight:900,fontSize:'1.3rem',color:col}}>{entry.score_pct}%</span>
              </div>
              <div style={{padding:'6px 12px',background:'var(--surface2)',borderRadius:7,fontSize:'0.82rem',color:'var(--text3)',marginBottom:6}}><strong>Model:</strong> {entry.model_answer}</div>
              <div style={{padding:'6px 12px',background:'var(--surface)',border:'1px solid var(--border)',borderRadius:7,fontSize:'0.85rem',marginBottom:10}}>
                <strong>🎤 Student said:</strong> <em>{entry.student_answer||'(no answer)'}</em>
              </div>
              {entry.missing&&entry.missing!=='None'&&<div style={{padding:'5px 10px',background:'rgba(217,119,6,.08)',border:'1px solid rgba(217,119,6,.2)',borderRadius:6,fontSize:'0.8rem',color:'#d97706',marginBottom:8}}>⚠ Missing: {entry.missing}</div>}
              <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:10,marginBottom:10}}>
                <div><label style={{display:'block',fontSize:'0.7rem',fontWeight:700,color:'var(--text3)',marginBottom:4,textTransform:'uppercase',fontFamily:'JetBrains Mono,monospace'}}>VERDICT</label>
                  <select className="form-select" value={entry.verdict} onChange={function(e){updateAnswer(i,'verdict',e.target.value);}}>
                    <option value="Correct">✅ Correct</option><option value="Partially Correct">⚠️ Partially Correct</option>
                    <option value="Incorrect">❌ Incorrect</option><option value="No Answer">— No Answer</option>
                  </select></div>
                <div><label style={{display:'block',fontSize:'0.7rem',fontWeight:700,color:'var(--text3)',marginBottom:4,textTransform:'uppercase',fontFamily:'JetBrains Mono,monospace'}}>SCORE %</label>
                  <input type="number" className="form-input" min={0} max={100} value={entry.score_pct} onChange={function(e){updateAnswer(i,'score_pct',Math.max(0,Math.min(100,Number(e.target.value))));}} /></div>
              </div>
              <div style={{marginBottom:8}}><label style={{display:'block',fontSize:'0.7rem',fontWeight:700,color:'var(--text3)',marginBottom:4,textTransform:'uppercase',fontFamily:'JetBrains Mono,monospace'}}>FEEDBACK</label>
                <textarea className="form-textarea" rows={2} value={entry.feedback} onChange={function(e){updateAnswer(i,'feedback',e.target.value);}}/></div>
              <div><label style={{display:'block',fontSize:'0.7rem',fontWeight:700,color:'var(--accent)',marginBottom:4,textTransform:'uppercase',fontFamily:'JetBrains Mono,monospace'}}>EXAMINER NOTES</label>
                <textarea className="form-textarea" rows={2} value={entry.notes} onChange={function(e){updateAnswer(i,'notes',e.target.value);}} style={{borderColor:'var(--accent-light)'}}/></div>
            </div>
          );
        })}
        <div style={{position:'sticky',bottom:20,textAlign:'center',marginTop:20}}>
          <button className="btn btn-success btn-lg" onClick={handleFinalize} disabled={finalizing}>{finalizing?'Saving…':'✅ Finalize & Save Results'}</button>
        </div>
      </div>
    );
  }

  // ════ FINAL ═════════════════════════════════════════════════
  if (phase==='final'&&results) {
    var fg=results.grade==='A'||results.grade==='A+'?'#16a34a':results.grade==='F'?'#dc2626':results.grade==='B'?'#2563eb':'#d97706';
    return (
      <div className="fade-up">
        <div style={{display:'flex',alignItems:'center',gap:12,marginBottom:24}}><div className="page-title">✅ Oral Viva Results Saved</div><span className="badge badge-success" style={{marginLeft:'auto'}}>Finalized</span></div>
        <div className="card" style={{marginBottom:20,textAlign:'center',padding:32,borderLeft:'4px solid '+fg}}>
          <div style={{fontFamily:'Space Grotesk,sans-serif',fontWeight:900,fontSize:'4rem',color:fg,lineHeight:1}}>{results.total_score||0}%</div>
          <div style={{fontFamily:'Space Grotesk,sans-serif',fontWeight:800,fontSize:'2rem',color:fg,marginTop:6}}>Grade {results.grade}</div>
          <div style={{display:'flex',gap:32,justifyContent:'center',marginTop:20}}>
            <div><div style={{fontWeight:700,fontSize:'1.3rem',color:'#16a34a'}}>{results.correct_count||0}</div><div style={{fontSize:'0.78rem',color:'var(--text3)'}}>Correct</div></div>
            <div><div style={{fontWeight:700,fontSize:'1.3rem',color:'#dc2626'}}>{(editableAnswers.length-(results.correct_count||0))}</div><div style={{fontSize:'0.78rem',color:'var(--text3)'}}>Incorrect</div></div>
          </div>
        </div>
        <div style={{display:'flex',gap:12}}><button className="btn btn-outline" onClick={function(){setPhase('results');}}>← Edit</button><button className="btn btn-primary" onClick={resetAll}>🔄 New Session</button></div>
      </div>
    );
  }

  // ════ ROOM ══════════════════════════════════════════════════
  var vivaId=savedVivaRef.current?savedVivaRef.current.viva_id:'';
  var q=questions[currentQ];
  var displayAnswer=fullAnswer+(liveWords?' '+liveWords:'');

  return (
    <div className="viva-dark fade-up">

      {/* Top bar */}
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:12,flexWrap:'wrap',gap:8}}>
        <div style={{display:'flex',gap:10,alignItems:'center',flexWrap:'wrap'}}>
          <span className="badge badge-danger">🔴 ORAL VIVA</span>
          <span style={{fontWeight:700,color:'#fff'}}>{title}</span>
          {/* Flow state indicator */}
          <span style={{padding:'3px 10px',borderRadius:20,background:'rgba(255,255,255,.08)',fontSize:'0.72rem',fontWeight:700,color:flowColor[flowState]||'#9ca3af'}}>{flowLabel[flowState]||flowState}</span>
          <span style={{fontFamily:'JetBrains Mono,monospace',fontSize:'0.72rem',color:'#9ca3af'}}>{transcript.length}/{questions.length} done</span>
        </div>
        <div style={{display:'flex',gap:6,flexWrap:'wrap'}}>
          <button className="btn btn-sm" style={{background:'rgba(255,255,255,.08)',color:'#e5e5e5',fontFamily:'JetBrains Mono,monospace',fontSize:'0.72rem'}} onClick={copyRoomId}>🔑 {vivaId.slice(0,8)}…</button>
          <button className="btn btn-sm" style={{background:unread>0?'rgba(220,38,38,.2)':'rgba(255,255,255,.08)',color:unread>0?'#f87171':'#e5e5e5',position:'relative'}} onClick={function(){setShowAlerts(!showAlerts);setUnread(0);}}>
            🔔{unread>0&&<span style={{position:'absolute',top:-4,right:-4,width:16,height:16,borderRadius:'50%',background:'#dc2626',color:'#fff',fontSize:'0.6rem',display:'flex',alignItems:'center',justifyContent:'center',fontWeight:700}}>{unread}</span>}
          </button>
          <button className="btn btn-sm btn-outline" onClick={function(){setShowInvite(!showInvite);if(!showInvite)loadStudents();}}>✉ Invite</button>
          <button className="btn btn-danger btn-sm" onClick={handleEndGrade} disabled={loading||transcript.length===0}>⏹ End &amp; Grade</button>
        </div>
      </div>

      {/* Alerts */}
      {showAlerts&&(<div className="card" style={{marginBottom:10,maxHeight:160,overflowY:'auto'}}>
        <div style={{fontSize:'0.7rem',fontWeight:700,color:'#9ca3af',letterSpacing:1,marginBottom:6,fontFamily:'JetBrains Mono,monospace'}}>STUDENT ACTIVITY</div>
        {alerts.length===0?<div style={{fontSize:'0.78rem',color:'#6b7280',textAlign:'center',padding:'6px 0'}}>No alerts…</div>
          :alerts.map(function(a,i){var col=a.type==='urgent'?'#dc2626':a.type==='success'?'#16a34a':'#d97706';return<div key={i} style={{padding:'5px 8px',borderLeft:'3px solid '+col,marginBottom:2}}><div style={{fontWeight:700,fontSize:'0.74rem',color:col}}>{a.title}</div></div>;})}
      </div>)}

      {/* Invite */}
      {showInvite&&(<div className="card" style={{marginBottom:10}}>
        <div style={{display:'flex',gap:6,marginBottom:8}}>{['account','email'].map(function(m){return<button key={m} onClick={function(){setInviteMode(m);}} className={'btn btn-sm '+(inviteMode===m?'btn-primary':'btn-outline')}>{m==='account'?'Account':'Email'}</button>;})}</div>
        {inviteMode==='account'?(<div><div style={{maxHeight:90,overflowY:'auto',display:'flex',flexWrap:'wrap',gap:5,marginBottom:6}}>{students.map(function(s){var sel=selectedStu.includes(s.user_id);return<div key={s.user_id} onClick={function(){toggleStudent(s.user_id);}} style={{padding:'3px 9px',borderRadius:20,border:'1px solid '+(sel?'var(--accent)':'rgba(255,255,255,.12)'),background:sel?'rgba(124,58,237,.2)':'transparent',color:sel?'#a78bfa':'#9ca3af',fontSize:'0.74rem',cursor:'pointer'}}>{s.name}</div>;})}</div>{selectedStu.length>0&&<button className="btn btn-primary btn-sm" onClick={sendInvites} disabled={inviting}>{inviting?'…':'Send to '+selectedStu.length}</button>}</div>):(<div style={{display:'flex',gap:6}}><input className="form-input" value={inviteEmail} onChange={function(e){setInviteEmail(e.target.value);}} placeholder="emails…" style={{flex:1}}/><button className="btn btn-primary btn-sm" onClick={sendInvites} disabled={inviting||!inviteEmail.trim()}>{inviting?'…':'Send'}</button></div>)}
        {inviteMsg&&<div style={{marginTop:5,fontSize:'0.74rem',color:inviteMsg.startsWith('Error')?'#f87171':'#4ade80'}}>{inviteMsg}</div>}
      </div>)}

      {/* ── 3-COL LAYOUT ── */}
      <div className="viva-3col">

        {/* LEFT: monitoring camera + controls */}
        <div style={{display:'flex',flexDirection:'column',gap:10,overflow:'auto'}}>

          {/* Admin camera — monitoring with face detection */}
          <div className="card" style={{padding:10}}>
            <div style={{fontSize:'0.68rem',fontWeight:700,color:'#9ca3af',letterSpacing:1,marginBottom:6,textAlign:'center',fontFamily:'JetBrains Mono,monospace'}}>📹 YOUR CAMERA</div>
            <div style={{position:'relative',borderRadius:8,overflow:'hidden',background:'#000',lineHeight:0}}>
              <video ref={videoRef} autoPlay muted playsInline
                style={{width:'100%',height:140,objectFit:'cover',display:'block'}}/>
              <canvas ref={canvasRef}
                style={{position:'absolute',top:0,left:0,width:'100%',height:'100%',pointerEvents:'none'}}/>
              {!camReady&&<div style={{position:'absolute',inset:0,display:'flex',alignItems:'center',justifyContent:'center',flexDirection:'column',gap:4}}><span style={{fontSize:'1.5rem',opacity:.4}}>📷</span><span style={{fontSize:'0.68rem',color:'#6b7280'}}>Starting…</span></div>}
            </div>
            <div style={{marginTop:5,padding:'4px 8px',borderRadius:5,background:'rgba(255,255,255,.06)',textAlign:'center',fontSize:'0.7rem',fontWeight:700,color:fsColor[faceStatus]||'#9ca3af'}}>
              {fsLabel[faceStatus]||faceStatus} {faceStatus==='ok'&&faceCount>0?'('+faceCount+')':''}
            </div>
          </div>

          {/* Student live video feed (WebRTC) */}
          <div className="card" style={{padding:10}}>
            <div style={{fontSize:'0.68rem',fontWeight:700,color:'#9ca3af',letterSpacing:1,marginBottom:6,textAlign:'center',fontFamily:'JetBrains Mono,monospace'}}>🎓 STUDENT</div>
            <div style={{position:'relative',borderRadius:8,overflow:'hidden',background:'#111',lineHeight:0}}>
              <video ref={studentVidRef} autoPlay playsInline
                style={{width:'100%',height:140,objectFit:'cover',display:'block'}}/>
              {!studentConnected&&<div style={{position:'absolute',inset:0,display:'flex',alignItems:'center',justifyContent:'center',flexDirection:'column',gap:4}}>
                <span style={{fontSize:'1.5rem',opacity:.3}}>👤</span>
                <span style={{fontSize:'0.66rem',color:'#4b5563'}}>Waiting for student…</span>
              </div>}
              {studentConnected&&<div style={{position:'absolute',bottom:4,left:'50%',transform:'translateX(-50%)',background:'rgba(22,163,74,.9)',color:'#fff',fontSize:'0.6rem',padding:'2px 8px',borderRadius:10,fontWeight:700,whiteSpace:'nowrap'}}>🟢 Live</div>}
            </div>
            <div style={{marginTop:5,fontSize:'0.68rem',color:studentConnected?'#4ade80':'#6b7280',textAlign:'center',fontWeight:700}}>
              {studentConnected ? '🟢 Student connected' : '⏳ Waiting to connect…'}
            </div>
          </div>

          {/* Violations log */}
          {violations.length>0&&(
            <div className="card" style={{padding:10}}>
              <div style={{fontSize:'0.68rem',fontWeight:700,color:'#dc2626',letterSpacing:1,marginBottom:6,fontFamily:'JetBrains Mono,monospace'}}>🚫 VIOLATIONS ({violations.length})</div>
              <div style={{maxHeight:120,overflowY:'auto'}}>
                {violations.map(function(v,i){return<div key={i} style={{fontSize:'0.7rem',color:'#f87171',padding:'3px 0',borderBottom:'1px solid rgba(255,255,255,.05)'}}>
                  <span style={{color:'#6b7280',marginRight:6}}>{v.time}</span>{v.msg}
                </div>;})}
              </div>
            </div>
          )}

          {/* Generator */}
          <div className="card" style={{padding:12}}>
            <div style={{fontSize:'0.68rem',fontWeight:700,color:'#9ca3af',letterSpacing:1,marginBottom:6,fontFamily:'JetBrains Mono,monospace'}}>⚡ GENERATE QUESTIONS</div>
            <input className="form-input" value={genTopic} onChange={function(e){setGenTopic(e.target.value);}} placeholder="Topic…" style={{marginBottom:5}}/>
            <div style={{display:'flex',gap:4,marginBottom:5}}>{[3,5,7,10].map(function(n){return<button key={n} onClick={function(){setGenCount(n);}} style={{flex:1,padding:'4px 0',borderRadius:5,border:'1px solid '+(genCount===n?'var(--accent)':'rgba(255,255,255,.1)'),background:genCount===n?'rgba(124,58,237,.25)':'transparent',color:genCount===n?'#a78bfa':'#9ca3af',fontSize:'0.75rem',fontWeight:700,cursor:'pointer'}}>{n}</button>;})}</div>
            <button className="btn btn-primary btn-sm" style={{width:'100%'}} onClick={handleGenerateQ} disabled={loading||!genTopic.trim()}>{loading?'…':'⚡ Add Qs'}</button>
          </div>

          {/* Custom Q */}
          <div className="card" style={{padding:12}}>
            <div style={{fontSize:'0.68rem',fontWeight:700,color:'#9ca3af',letterSpacing:1,marginBottom:6,fontFamily:'JetBrains Mono,monospace'}}>✏ YOUR QUESTION</div>
            {!showCustomQ?<button className="btn btn-outline btn-sm" style={{width:'100%'}} onClick={function(){setShowCustomQ(true);}}>+ Add Custom Q</button>:(
              <div>
                <textarea className="form-textarea" rows={2} value={customQuestion} onChange={function(e){setCustomQuestion(e.target.value);}} placeholder="Your question…" style={{marginBottom:4}}/>
                <textarea className="form-textarea" rows={2} value={customModelAns} onChange={function(e){setCustomModelAns(e.target.value);}} placeholder="Model answer (blank = AI generates)" style={{marginBottom:5}}/>
                <div style={{display:'flex',gap:5}}>
                  <button className="btn btn-success btn-sm" style={{flex:1}} onClick={handleAddCustomQuestion} disabled={!customQuestion.trim()||genModel}>{genModel?'…':customModelAns.trim()?'Add':'Add+AI'}</button>
                  <button className="btn btn-ghost btn-sm" onClick={function(){setShowCustomQ(false);setCustomQuestion('');setCustomModelAns('');}}>✕</button>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* MIDDLE: question + oral answer */}
        <div style={{display:'flex',flexDirection:'column',gap:10,overflow:'auto'}}>

          {/* Start viva button if not started */}
          {flowState==='idle'&&questions.length>0&&transcript.length===0&&(
            <div style={{textAlign:'center',padding:'16px 0'}}>
              <button className="btn btn-success btn-lg" onClick={startVivaFlow} style={{boxShadow:'0 4px 20px rgba(22,163,74,.4)'}}>
                🎙 Start Oral Viva
              </button>
              <div style={{fontSize:'0.8rem',color:'#9ca3af',marginTop:8}}>Will read first question aloud and begin capturing student's answer</div>
            </div>
          )}

          {q ? (
            <div className="card">
              <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:10,flexWrap:'wrap',gap:6}}>
                <div style={{display:'flex',gap:6,alignItems:'center'}}>
                  <span className="badge badge-primary">Q{currentQ+1}/{questions.length}</span>
                  {q._custom&&<span className="badge badge-warning" style={{fontSize:'0.65rem'}}>✏ Your Q</span>}
                </div>
                <div style={{display:'flex',gap:5,alignItems:'center'}}>
                  <span style={{fontSize:'0.7rem',fontWeight:700,color:flowColor[flowState]||'#9ca3af'}}>{flowLabel[flowState]}</span>
                  <button onClick={function(){speakQuestion(q.question);}} disabled={flowState==='speaking'}
                    style={{padding:'4px 10px',borderRadius:6,border:'none',background:'rgba(124,58,237,.25)',color:'#a78bfa',fontWeight:700,fontSize:'0.72rem',cursor:flowState==='speaking'?'default':'pointer'}}>
                    🔊 Read Aloud
                  </button>
                </div>
              </div>

              {/* Question */}
              <div style={{padding:'10px 14px',background:'rgba(124,58,237,.12)',border:'1px solid rgba(124,58,237,.25)',borderRadius:9,marginBottom:10,fontWeight:700,fontSize:'1rem',color:'#e5e5e5',lineHeight:1.55}}>{q.question}</div>

              {/* Model answer */}
              <div style={{padding:'7px 12px',background:'rgba(22,163,74,.08)',border:'1px solid rgba(22,163,74,.15)',borderRadius:7,fontSize:'0.8rem',color:'#4ade80',marginBottom:12}}>
                <div style={{fontSize:'0.6rem',fontWeight:700,letterSpacing:1,marginBottom:3,fontFamily:'JetBrains Mono,monospace',color:'#6b7280'}}>MODEL ANSWER (Examiner Only)</div>
                {q.model_answer}
              </div>

              {/* Live transcript box */}
              <div style={{marginBottom:10}}>
                <div style={{display:'flex',justifyContent:'space-between',marginBottom:5}}>
                  <label style={{fontSize:'0.7rem',fontWeight:700,color:'#9ca3af',textTransform:'uppercase',letterSpacing:1,fontFamily:'JetBrains Mono,monospace'}}>
                    🎤 Student's Answer {flowState==='listening'&&<span style={{color:'#dc2626',marginLeft:6}}>● Auto-capturing</span>}
                  </label>
                  {(fullAnswer||liveWords)&&<button onClick={function(){setFullAnswer('');fullAnswerRef.current='';setLiveWords('');setManualAnswer('');setVerdict(null);}} style={{fontSize:'0.7rem',color:'#9ca3af',background:'transparent',border:'none',cursor:'pointer'}}>🗑 Clear</button>}
                </div>
                {/* Live words display */}
                <div style={{minHeight:70,padding:'9px 12px',background:'rgba(255,255,255,.05)',border:'1.5px solid '+(flowState==='listening'?'#dc2626':'rgba(255,255,255,.1)'),borderRadius:8,fontSize:'0.9rem',color:'#e5e5e5',lineHeight:1.6,transition:'border-color .2s',marginBottom:6}}>
                  {displayAnswer||<span style={{color:'#4b5563',fontStyle:'italic'}}>{flowState==='listening'?'Listening… student should speak now':'Waiting…'}</span>}
                </div>
                {/* Manual type fallback */}
                <textarea className="form-textarea" rows={2} value={manualAnswer} onChange={function(e){setManualAnswer(e.target.value);}}
                  placeholder="Or type / correct the answer manually…"
                  style={{fontSize:'0.84rem',background:'rgba(255,255,255,.04)',border:'1px solid rgba(255,255,255,.07)',color:'#e5e5e5',marginBottom:0}}/>
              </div>

              {/* Examiner notes */}
              <div style={{marginBottom:10}}>
                <label style={{display:'block',fontSize:'0.7rem',fontWeight:700,color:'#9ca3af',marginBottom:4,textTransform:'uppercase',letterSpacing:1,fontFamily:'JetBrains Mono,monospace'}}>Examiner Notes</label>
                <textarea className="form-textarea" rows={2} value={examinerNotes} onChange={function(e){setExaminerNotes(e.target.value);}} placeholder="Confidence, hesitation, body language…" style={{background:'rgba(255,255,255,.04)',border:'1px solid rgba(255,255,255,.07)',color:'#e5e5e5'}}/>
              </div>

              {/* Verdict */}
              {verdict&&(
                <div style={{padding:10,background:verdict.correct?'rgba(22,163,74,.12)':'rgba(220,38,38,.12)',borderRadius:8,marginBottom:10,border:'1px solid '+(verdict.correct?'rgba(22,163,74,.3)':'rgba(220,38,38,.3)')}}>
                  <div style={{display:'flex',justifyContent:'space-between',marginBottom:4}}>
                    <span style={{fontWeight:700,color:verdict.correct?'#4ade80':'#f87171'}}>{verdict.verdict}</span>
                    <span style={{fontWeight:900,fontSize:'1.1rem',color:'#a78bfa'}}>{verdict.score_pct}%</span>
                  </div>
                  <div style={{fontSize:'0.8rem',color:'#d1d5db'}}>{verdict.feedback}</div>
                  {verdict.missing&&verdict.missing!=='None'&&<div style={{fontSize:'0.72rem',color:'#fbbf24',marginTop:3}}>Missing: {verdict.missing}</div>}
                </div>
              )}

              {/* Manual controls */}
              <div style={{display:'flex',gap:7}}>
                <button className="btn btn-warning btn-sm" style={{flex:1}} onClick={handleManualGradeAndSave} disabled={flowState==='grading'||(!displayAnswer&&!manualAnswer.trim())}>
                  {flowState==='grading'?'Grading…':'⚡ Grade & Save (Manual)'}
                </button>
                {flowState==='idle'&&questions.length>0&&(
                  <button className="btn btn-primary btn-sm" onClick={function(){speakQuestion(q.question);}}>🔊 Re-read</button>
                )}
              </div>
              {autoMsg&&<div style={{marginTop:6,fontSize:'0.75rem',color:'#4ade80',textAlign:'center'}}>{autoMsg}</div>}
            </div>
          ) : (
            <div className="card" style={{display:'flex',alignItems:'center',justifyContent:'center',minHeight:200}}>
              <div style={{textAlign:'center',color:'#9ca3af'}}><div style={{fontSize:'2.5rem',marginBottom:10}}>🎤</div><div style={{fontWeight:600}}>Add questions to begin</div></div>
            </div>
          )}
        </div>

        {/* RIGHT: question list + transcript */}
        <div style={{display:'flex',flexDirection:'column',gap:10,overflow:'auto'}}>

          <div className="card" style={{padding:12}}>
            <div style={{fontSize:'0.68rem',fontWeight:700,color:'#9ca3af',letterSpacing:1,marginBottom:7,fontFamily:'JetBrains Mono,monospace'}}>QUESTIONS ({questions.length})</div>
            <div style={{maxHeight:200,overflowY:'auto'}}>
              {questions.length===0?<div style={{fontSize:'0.75rem',color:'#4b5563',textAlign:'center',padding:'8px 0'}}>None yet</div>
                :questions.map(function(q2,i){var done=i<transcript.length,isCur=i===currentQ;
                  return<div key={i} onClick={function(){if(flowState==='idle'){setCurrentQ(i);currentQRef.current=i;setFullAnswer('');fullAnswerRef.current='';setManualAnswer('');setVerdict(null);}}} style={{padding:'5px 7px',borderRadius:5,cursor:flowState==='idle'?'pointer':'default',marginBottom:2,background:isCur?'rgba(124,58,237,.18)':'transparent',fontSize:'0.73rem',color:done?'#4ade80':isCur?'#e5e5e5':'#9ca3af',borderLeft:isCur?'3px solid var(--accent)':'3px solid transparent',display:'flex',gap:4,alignItems:'center'}}>
                    {q2._custom&&<span style={{fontSize:'0.58rem',color:'#f59e0b',flexShrink:0}}>✏</span>}
                    <span style={{flexShrink:0}}>{done?'✓':'○'}{i+1}.</span>
                    <span style={{overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{(q2.question||'').slice(0,36)}{(q2.question||'').length>36?'…':''}</span>
                  </div>;})}
            </div>
          </div>

          {/* Auto-generated transcript */}
          <div className="card" style={{padding:12,flex:1,overflow:'auto'}}>
            <div style={{fontSize:'0.68rem',fontWeight:700,color:'#9ca3af',letterSpacing:1,marginBottom:7,fontFamily:'JetBrains Mono,monospace'}}>📝 TRANSCRIPT ({transcript.length}) — Auto-generated</div>
            {transcript.length===0?<div style={{fontSize:'0.75rem',color:'#4b5563',textAlign:'center',padding:'8px 0'}}>Auto-generated as student answers</div>
              :transcript.map(function(t,i){
                var v=t.verdict; var col=v?(v.correct?'#4ade80':v.verdict==='Partially Correct'?'#fbbf24':'#f87171'):'#9ca3af';
                return<div key={i} style={{padding:'7px 0',borderBottom:'1px solid rgba(255,255,255,.06)'}}>
                  <div style={{display:'flex',justifyContent:'space-between',marginBottom:3}}>
                    <div style={{display:'flex',gap:4,alignItems:'center'}}>
                      <span style={{fontWeight:700,fontSize:'0.75rem',color:'#e5e5e5'}}>Q{i+1}</span>
                      {t._custom&&<span style={{fontSize:'0.58rem',color:'#f59e0b'}}>✏</span>}
                    </div>
                    {v&&<span style={{fontWeight:700,fontSize:'0.72rem',color:col}}>{v.score_pct}% · {v.verdict}</span>}
                  </div>
                  <div style={{fontSize:'0.68rem',color:'#a78bfa',marginBottom:2}}>Q: {(t.question||'').slice(0,48)}{(t.question||'').length>48?'…':''}</div>
                  <div style={{fontSize:'0.68rem',color:'#9ca3af'}}>A: {(t.student_answer||'(none)').slice(0,55)}{(t.student_answer||'').length>55?'…':''}</div>
                </div>;
              })}
          </div>
        </div>
      </div>
    </div>
  );
}
